PRAGMA foreign_keys=ON;
CREATE TABLE teams(team_id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE employees(employee_id TEXT PRIMARY KEY,team_id TEXT NOT NULL REFERENCES teams(team_id) DEFERRABLE INITIALLY DEFERRED,manager_id TEXT REFERENCES employees(employee_id) DEFERRABLE INITIALLY DEFERRED,role TEXT NOT NULL,email TEXT);
CREATE TABLE tickets(ticket_id TEXT PRIMARY KEY,assignee_id TEXT NOT NULL REFERENCES employees(employee_id) DEFERRABLE INITIALLY DEFERRED,status TEXT NOT NULL);
CREATE TABLE notes(note_id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES tickets(ticket_id) DEFERRABLE INITIALLY DEFERRED,kind TEXT NOT NULL,private_text TEXT);
